  "it_manager_acknowledged_at" timestamp(0) NULL DEFAULT NULL,
  "it_manager_user_id" bigint DEFAULT NULL,
  "it_manager_remarks" text,
  "it_notes" text,
  "asset_changes" text,
  "pending_asset_ids" jsonb DEFAULT NULL,
  "acknowledged_at" timestamp(0) NULL DEFAULT NULL,
  "acknowledgement_token" varchar(255) DEFAULT NULL,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);

