CREATE UNIQUE INDEX "payslips_payslip_number_unique" ON "payslips" ("payslip_number");

CREATE TABLE "personal_details" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "onboarding_id" bigint NOT NULL,
  "full_name" varchar(255) DEFAULT NULL,
  "preferred_name" varchar(100) DEFAULT NULL,
  "official_document_id" varchar(255) DEFAULT NULL,
  "date_of_birth" date DEFAULT NULL,
  "sex" varchar(255) DEFAULT NULL,
  "marital_status" varchar(255) DEFAULT NULL,
  "religion" varchar(255) DEFAULT NULL,
  "race" varchar(255) DEFAULT NULL,
  "is_disabled" boolean NOT NULL DEFAULT false,
  "residential_address" text,
  "personal_contact_number" varchar(255) DEFAULT NULL,
  "house_tel_no" varchar(255) DEFAULT NULL,
  "personal_email" varchar(255) DEFAULT NULL,
  "bank_account_number" varchar(255) DEFAULT NULL,
  "bank_name" varchar(255) DEFAULT NULL,
  "epf_no" varchar(255) DEFAULT NULL,
  "income_tax_no" varchar(255) DEFAULT NULL,
  "socso_no" varchar(255) DEFAULT NULL,
  "nric_file_path" varchar(255) DEFAULT NULL,
  "nric_file_paths" jsonb DEFAULT NULL,
  "consent_given_at" timestamp(0) NULL DEFAULT NULL,
  "consent_ip" varchar(45) DEFAULT NULL,
  "invite_staging_json" text,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "public_holidays" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "company" varchar(255) DEFAULT NULL,
  "name" varchar(255) NOT NULL,
  "date" date NOT NULL,
  "year" smallint NOT NULL,
  "is_recurring" boolean NOT NULL DEFAULT false,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "public_holidays_company_date_unique" ON "public_holidays" ("company","date");

CREATE TABLE "salary_adjustments" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "employee_id" bigint NOT NULL,
  "adjusted_by" bigint DEFAULT NULL,
  "type" varchar(30) NOT NULL,
  "previous_salary" decimal(12,2) NOT NULL,
  "new_salary" decimal(12,2) NOT NULL,
  "effective_date" date NOT NULL,
  "reason" text,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "security_audit_logs" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint DEFAULT NULL,
  "work_email" varchar(255) DEFAULT NULL,
  "role" varchar(255) DEFAULT NULL,
  "event_type" varchar(255) NOT NULL,
  "url" varchar(255) DEFAULT NULL,
  "method" varchar(10) DEFAULT NULL,
  "ip_address" varchar(45) DEFAULT NULL,
  "details" text,
  "emailed" boolean NOT NULL DEFAULT false,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "user_permissions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "resource" varchar(100) NOT NULL,
  "access_level" varchar(255) NOT NULL,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_permissions_access_level_check" CHECK ("access_level" IN ('full','view','edit','none'))
);

CREATE UNIQUE INDEX "user_permissions_user_id_resource_unique" ON "user_permissions" ("user_id","resource");

CREATE TABLE "users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(255) NOT NULL,
  "work_email" varchar(255) NOT NULL,
  "password" varchar(255) NOT NULL,
  "two_factor_secret" text,
  "two_factor_recovery_codes" text,
  "two_factor_confirmed_at" timestamp(0) NULL DEFAULT NULL,
  "role" varchar(255) DEFAULT 'employee',
  "kb_password_hash" varchar(255) DEFAULT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "login_attempts" smallint NOT NULL DEFAULT '0',
  "deactivation_reason" varchar(255) DEFAULT NULL,
  "deactivated_at" timestamp(0) NULL DEFAULT NULL,
  "session_token" varchar(255) DEFAULT NULL,
  "profile_picture" varchar(255) DEFAULT NULL,
  "remember_token" varchar(100) DEFAULT NULL,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "users_role_check" CHECK ("role" IN ('hr_manager','hr_executive','hr_intern','it_manager','it_executive','it_intern','superadmin','system_admin','employee','finance_manager','finance_executive'))
);

CREATE UNIQUE INDEX "users_work_email_unique" ON "users" ("work_email");

CREATE TABLE "work_details" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "onboarding_id" bigint NOT NULL,
  "employee_number" varchar(50) DEFAULT NULL,
  "employee_status" varchar(255) DEFAULT NULL,
  "staff_status" varchar(255) DEFAULT NULL,
  "employment_type" varchar(255) DEFAULT NULL,
  "designation" varchar(255) DEFAULT NULL,
  "company" varchar(255) DEFAULT NULL,
  "office_location" varchar(255) DEFAULT NULL,
  "reporting_manager" varchar(255) DEFAULT NULL,
  "reporting_manager_email" varchar(255) DEFAULT NULL,
  "start_date" date DEFAULT NULL,
  "exit_date" date DEFAULT NULL,
  "last_salary_date" date DEFAULT NULL,
  "confirmation_date" date DEFAULT NULL,
  "company_email" varchar(255) DEFAULT NULL,
  "google_id" varchar(255) DEFAULT NULL,
  "role" varchar(255) DEFAULT NULL,
  "department" varchar(255) DEFAULT NULL,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "work_details_role_check" CHECK ("role" IN ('manager','senior_executive','executive_associate','director_hod','hr_manager','hr_executive','hr_intern','it_manager','it_executive','it_intern','superadmin','system_admin','others'))
);

CREATE TABLE "work_schedules" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "company" varchar(255) DEFAULT NULL,
  "name" varchar(255) NOT NULL,
  "start_time" time NOT NULL,
  "end_time" time NOT NULL,
  "break_start" time DEFAULT NULL,
  "break_end" time DEFAULT NULL,
  "work_hours_per_day" decimal(4,2) NOT NULL,
  "working_days" jsonb DEFAULT NULL,
  "is_default" boolean NOT NULL DEFAULT false,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp(0) NULL DEFAULT NULL,
  "updated_at" timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);



